-- Verified 2026-11-04: columns (31 tables), functions (5), triggers (10) and policies (46) reproduce
-- production's hashes exactly; constraint/index/grant/RLS counts match. Function bodies use CRLF line
-- endings exactly as in production (kept by .gitattributes). Not yet applied to staging or production.
-- 0000_baseline: structure of the LIVE production database as captured on 2026-11-04.
--
-- Source: read-only catalog queries run by the owner on production (Postgres 17.6).
-- NOT taken from the old repo's supabase/schema.sql. Generated by a catalog query, not pg_dump.
-- Contains no table rows. The only data statements are the 4 storage bucket CONFIG rows at the end.
-- Not included on purpose: Supabase-managed event triggers (ensure_rls etc.), the auth and storage
-- schemas themselves, and ownership (everything is owned by postgres).
-- Applying this to production must change nothing. Staging first. Production only with owner approval.

set check_function_bodies = off;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists pg_stat_statements with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists supabase_vault with schema vault;
create sequence if not exists public.request_display_id_seq as bigint start with 1050 increment by 1 minvalue 1 maxvalue 9223372036854775807 cache 1;
CREATE OR REPLACE FUNCTION public.current_client_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT client_id FROM public.client_users WHERE auth_user_id = auth.uid() LIMIT 1
$function$
;
CREATE OR REPLACE FUNCTION public.next_request_display_id()
 RETURNS text
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  SELECT 'LUM-' || nextval('request_display_id_seq')::text
$function$
;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.user_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT role FROM public.profiles WHERE id = auth.uid()),
    'none'   -- no profile row => no role => no access. Do not change this.
  )
$function$
;
